parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "document_type",
    "document_confidence",
    "claimant_name",
    "policy_number",
    "claim_number",
    "vehicle_make",
    "vehicle_model",
    "vehicle_registration",
    "vin",
    "incident_date",
    "incident_time",
    "country",
    "city",
    "repair_estimate_amount",
    "currency",
    "people_involved",
    "injuries_reported",
    "document_complete",
    "fraud_indicators",
    "document_summary",
    "confidence_score"
  ],
  "properties": {
    "document_type": {
      "type": [
        "string",
        "null"
      ],
      "description": "Detected insurance document classification."
    },

    "document_confidence": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "maximum": 1,
      "description": "Confidence score for document classification."
    },

    "claimant_name": {
      "type": [
        "string",
        "null"
      ],
      "description": "Full claimant name explicitly present in OCR text."
    },

    "policy_number": {
      "type": [
        "string",
        "null"
      ],
      "description": "Insurance policy identifier."
    },

    "claim_number": {
      "type": [
        "string",
        "null"
      ],
      "description": "Insurance claim reference number."
    },

    "vehicle_make": {
      "type": [
        "string",
        "null"
      ],
      "description": "Vehicle manufacturer."
    },

    "vehicle_model": {
      "type": [
        "string",
        "null"
      ],
      "description": "Vehicle model."
    },

    "vehicle_registration": {
      "type": [
        "string",
        "null"
      ],
      "description": "Normalized vehicle registration identifier."
    },

    "vin": {
      "type": [
        "string",
        "null"
      ],
      "description": "Vehicle Identification Number."
    },

    "incident_date": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$",
      "description": "Incident date normalized to YYYY-MM-DD."
    },

    "incident_time": {
      "type": [
        "string",
        "null"
      ],
      "description": "Incident time if explicitly present."
    },

    "country": {
      "type": [
        "string",
        "null"
      ],
      "description": "Country where incident occurred."
    },

    "city": {
      "type": [
        "string",
        "null"
      ],
      "description": "City where incident occurred."
    },

    "repair_estimate_amount": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "description": "Estimated repair amount normalized to numeric format."
    },

    "currency": {
      "type": [
        "string",
        "null"
      ],
      "description": "Detected currency code or symbol."
    },

    "people_involved": {
      "type": "array",
      "description": "List of explicitly mentioned involved persons.",
      "items": {
        "type": "string"
      }
    },

    "injuries_reported": {
      "type": [
        "boolean",
        "null"
      ],
      "description": "Whether injuries were explicitly reported."
    },

    "document_complete": {
      "type": [
        "boolean",
        "null"
      ],
      "description": "Whether the document appears complete and sufficiently readable."
    },

    "fraud_indicators": {
      "type": "array",
      "description": "Observable inconsistencies or suspicious patterns directly supported by OCR text.",
      "items": {
        "type": "string"
      }
    },

    "document_summary": {
      "type": [
        "string",
        "null"
      ],
      "description": "Professional concise summary of the document contents."
    },

    "confidence_score": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Overall extraction confidence score."
    }
  }
}
